import { Entity, Column, PrimaryGeneratedColumn, ManyToOne, ManyToMany, JoinTable } from 'typeorm';
import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
@Module({ imports: [TypeOrmModule.forRoot({ type: 'mysql' })] })
export class AppModule {}
@Entity('user')
export class UserEntity {
  @PrimaryGeneratedColumn() id: number;
  @Column() email: string;
  @Column({ name: 'pass_hash' }) password: string;
  @ManyToMany(() => ArticleEntity) @JoinTable() favorites: ArticleEntity[];
}
@Entity()
export class ArticleEntity {
  @PrimaryGeneratedColumn() id: number;
  @Column('varchar', { name: 'headline' }) title: string;
  @ManyToOne(() => UserEntity) author: UserEntity;
}

