import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './user.entity';
@Injectable()
export class UsersService {
  constructor(@InjectRepository(User) private readonly users: Repository<User>) {}
  byEmail(email: string) { return this.users.findOneBy({ email }); }
}

import { DataSource, EntityManager } from 'typeorm';
export class Orders {
  constructor(private ds: DataSource, private em: EntityManager) {}
  a() { return this.ds.getRepository(Order).find(); }
  b() { return this.em.find(Order, { where: { id: 1 } }); }
  c() { return this.ds.transaction(async (m) => { await m.save(Order, { id: 1 }); }); }
}
class Order {}

import { Repository, EntityRepository, getRepository } from 'typeorm';
@EntityRepository(Tag)
export class TagRepository extends Repository<Tag> {
  popular() { return this.find({ order: { uses: 'DESC' } }); }
}
export function all() { return getRepository(Tag).count(); }
class Tag {}

